package com.fincore.fincore.transaction; import jakarta.validation.Valid; import org.springframework.data.domain.*;
import org.springframework.data.web.PageableDefault;
import org.springframework.http.*; import org.springframework.security.core.annotation.AuthenticationPrincipal; import org.springframework.web.bind.annotation.*; import com.fincore.fincore.security.AuthenticatedUser; @RestController @RequestMapping("/api/v1/transactions") public class TransactionController {private final TransactionService service;public TransactionController(TransactionService s){service=s;}@PostMapping ResponseEntity<TransactionResponse> create(@AuthenticationPrincipal AuthenticatedUser u,@Valid @RequestBody CreateTransactionRequest r){return ResponseEntity.status(201).body(service.create(u.id(),r));}@GetMapping Page<TransactionResponse> all(@AuthenticationPrincipal AuthenticatedUser u,@PageableDefault(size=20,sort="occurredAt",direction=Sort.Direction.DESC) Pageable p){return service.all(u.id(),p);}@GetMapping("/{id}") TransactionResponse one(@AuthenticationPrincipal AuthenticatedUser u,@PathVariable Long id){return service.one(u.id(),id);}}
